pub fn add(a: i64, b: i64) -> i64 {
    a + b
}

// SPDX-License-Identifier: GPL-3.0-or-later
// Copyright (c) 2026 Ada Example

pub fn floor_div(a: i64, b: i64) -> i64 {
    let q = a / b;
    let r = a % b;
    if r != 0 && ((r > 0) != (b > 0)) {
        q - 1
    } else {
        q
    }
}

pub fn remainder(a: i64, b: i64) -> i64 {
    a - floor_div(a, b) * b
}

