pub fn clamp(n: i64, low: i64, high: i64) -> i64 {
    std::cmp::min(std::cmp::max(n, low), high)
}

// SPDX-License-Identifier: GPL-3.0-or-later
// Copyright (c) 2026 Ada Example

pub fn total(n: i64) -> i64 {
    let mut result: i64 = 0;
    let mut i: i64 = 0;
    while i < n {
        result += i;
        i += 1;
    }
    result
}

